 * Unit tests for pricingService
 * MODULE-04 LISTING-V3: TASK LISTING-V3-010
 * Tests tier math with seeded avg, empty-data fallback
 */

import * as pricingService from '../../services/pricingService';
import { supabase } from '../../config/supabase';

// Mock supabase
jest.mock('../../config/supabase', () => ({
  supabase: {
    from: jest.fn(),
  },
}));

const mockSupabase = supabase as jest.Mocked<typeof supabase>;

describe('pricingService', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('getSuggestedPrice', () => {
    it('should return empty array when no categoryId provided', async () => {
      const result = await pricingService.getSuggestedPrice(undefined, 'good');

      expect(result).toEqual([]);
      expect(mockSupabase.from).not.toHaveBeenCalled();
    });

    it('should return empty array when fewer than 5 comparable sales', async () => {
      const mockQuery = {
        select: jest.fn().mockReturnThis(),
        eq: jest.fn().mockReturnThis(),
        gte: jest.fn().mockResolvedValue({
          data: [
            { price: 10.0 },
            { price: 12.0 },
            { price: 15.0 },
          ], // Only 3 items
          error: null,
        }),
      };

      mockSupabase.from = jest.fn(() => mockQuery) as any;

      const result = await pricingService.getSuggestedPrice('cat-123', 'good');

      expect(result).toEqual([]);
    });

    it('should return 4 tiers when sufficient data available', async () => {
      const mockQuery = {
        select: jest.fn().mockReturnThis(),
        eq: jest.fn().mockReturnThis(),
        gte: jest.fn().mockResolvedValue({
          data: [
            { price: 20.0 },
            { price: 22.0 },
            { price: 18.0 },
            { price: 25.0 },
            { price: 15.0 },
          ], // 5 items, avg = 100 / 5 = 20.0
          error: null,
        }),
      };

      mockSupabase.from = jest.fn(() => mockQuery) as any;

      const result = await pricingService.getSuggestedPrice('cat-123', 'good');

      expect(result).toHaveLength(4);

      // Verify tier structure
      expect(result[0].tier).toBe('great_deal');
      expect(result[1].tier).toBe('fair_price');
      expect(result[2].tier).toBe('asking_price');
      expect(result[3].tier).toBe('almost_new');

      // Verify tier calculations (avg = 20.0)
      // great_deal: 20 * 0.45 = 9.0
      expect(result[0].price).toBe(9.0);
      expect(result[0].label).toBe('Great Deal');

      // fair_price: 20 * 0.60 = 12.0
      expect(result[1].price).toBe(12.0);
      expect(result[1].label).toBe('Fair Price');

      // asking_price: 20 * 0.75 = 15.0
      expect(result[2].price).toBe(15.0);
      expect(result[2].label).toBe('Asking Price');

      // almost_new: 20 * 0.90 = 18.0
      expect(result[3].price).toBe(18.0);
      expect(result[3].label).toBe('Almost New');
    });

    it('should round prices to 2 decimal places', async () => {
      const mockQuery = {
        select: jest.fn().mockReturnThis(),
        eq: jest.fn().mockReturnThis(),
        gte: jest.fn().mockResolvedValue({
          data: [
            { price: 10.55 },
            { price: 11.33 },
            { price: 9.88 },
            { price: 12.44 },
            { price: 10.10 },
          ], // avg = 54.3 / 5 = 10.86
          error: null,
        }),
      };

      mockSupabase.from = jest.fn(() => mockQuery) as any;

      const result = await pricingService.getSuggestedPrice('cat-123');

      // great_deal: 10.86 * 0.45 = 4.887 → rounds to 4.89
      expect(result[0].price).toBe(4.89);

      // fair_price: 10.86 * 0.60 = 6.516 → rounds to 6.52
      expect(result[1].price).toBe(6.52);

      // asking_price: 10.86 * 0.75 = 8.145 → rounds to 8.15
      expect(result[2].price).toBe(8.15);

      // almost_new: 10.86 * 0.90 = 9.774 → rounds to 9.77
      expect(result[3].price).toBe(9.77);
    });

    it('should filter by condition when provided', async () => {
      const mockQuery = {
        select: jest.fn().mockReturnThis(),
        eq: jest.fn().mockReturnThis(),
        gte: jest.fn().mockResolvedValue({
          data: Array(10).fill({ price: 15.0 }),
          error: null,
        }),
      };

      mockSupabase.from = jest.fn(() => mockQuery) as any;

      await pricingService.getSuggestedPrice('cat-123', 'like_new');

      // Verify condition filter was applied
      expect(mockQuery.eq).toHaveBeenCalledWith('condition', 'like_new');
    });

    it('should not filter by condition when not provided', async () => {
      const mockQuery = {
        select: jest.fn().mockReturnThis(),
        eq: jest.fn().mockReturnThis(),
        gte: jest.fn().mockResolvedValue({
          data: Array(10).fill({ price: 15.0 }),
          error: null,
        }),
      };

      mockSupabase.from = jest.fn(() => mockQuery) as any;

      await pricingService.getSuggestedPrice('cat-123');

      // Verify eq was called twice (category_id and status), but not for condition
      const eqCalls = mockQuery.eq.mock.calls;
      expect(eqCalls).toHaveLength(2);
      expect(eqCalls[0]).toEqual(['category_id', 'cat-123']);
      expect(eqCalls[1]).toEqual(['status', 'sold']);
    });

    it('should query sold items within 90-day lookback window', async () => {
      const mockQuery = {
        select: jest.fn().mockReturnThis(),
        eq: jest.fn().mockReturnThis(),
        gte: jest.fn().mockResolvedValue({
          data: Array(10).fill({ price: 15.0 }),
          error: null,
        }),
      };

      mockSupabase.from = jest.fn(() => mockQuery) as any;

      const beforeCall = new Date();
      await pricingService.getSuggestedPrice('cat-123');
      const afterCall = new Date();

      // Verify gte was called with a date ~90 days ago
      expect(mockQuery.gte).toHaveBeenCalled();
      const gteCall = mockQuery.gte.mock.calls[0];
      expect(gteCall[0]).toBe('sold_at');

      // Parse the ISO date passed
      const lookbackDate = new Date(gteCall[1]);
      const expectedLookback = new Date();
      expectedLookback.setDate(expectedLookback.getDate() - 90);

      // Allow 1-day tolerance for test execution time
      const dayDiff = Math.abs(lookbackDate.getTime() - expectedLookback.getTime()) / (1000 * 60 * 60 * 24);
      expect(dayDiff).toBeLessThan(1);
    });

    it('should handle database error gracefully', async () => {
      const mockQuery = {
        select: jest.fn().mockReturnThis(),
        eq: jest.fn().mockReturnThis(),
        gte: jest.fn().mockResolvedValue({
          data: null,
          error: { message: 'Database connection failed' },
        }),
      };

      mockSupabase.from = jest.fn(() => mockQuery) as any;

      const result = await pricingService.getSuggestedPrice('cat-123');

      // Should return empty array on error
      expect(result).toEqual([]);
    });

    it('should include descriptions for each tier', async () => {
      const mockQuery = {
        select: jest.fn().mockReturnThis(),
        eq: jest.fn().mockReturnThis(),
        gte: jest.fn().mockResolvedValue({
          data: Array(10).fill({ price: 20.0 }),
          error: null,
        }),
      };

      mockSupabase.from = jest.fn(() => mockQuery) as any;

      const result = await pricingService.getSuggestedPrice('cat-123');

      expect(result[0].description).toBe('Quick sale, excellent value');
      expect(result[1].description).toBe('Competitive pricing');
      expect(result[2].description).toBe('Market average');
      expect(result[3].description).toBe('Premium pricing for excellent condition');
    });
  });
});
"}

