 * Unit tests for categoryService
 * MODULE-04 LISTING-V3: TASK LISTING-V3-010
 * Tests flagForCategoryReview idempotency, recent category LRU
 */

import * as categoryService from '../../services/categoryService';
import { supabase } from '../../config/supabase';
import AsyncStorage from '@react-native-async-storage/async-storage';

// Mock supabase
jest.mock('../../config/supabase', () => ({
  supabase: {
    from: jest.fn(),
  },
}));

// Mock AsyncStorage
jest.mock('@react-native-async-storage/async-storage', () => ({
  getItem: jest.fn(),
  setItem: jest.fn(),
  removeItem: jest.fn(),
}));

const mockSupabase = supabase as jest.Mocked<typeof supabase>;
const mockAsyncStorage = AsyncStorage as jest.Mocked<typeof AsyncStorage>;

describe('categoryService', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('flagForCategoryReview', () => {
    it('should update item with requested category name and create review flag', async () => {
      const mockUpdateQuery = {
        update: jest.fn().mockReturnThis(),
        eq: jest.fn().mockResolvedValue({ data: {}, error: null }),
      };

      const mockUpsertQuery = {
        upsert: jest.fn().mockResolvedValue({ data: {}, error: null }),
      };

      mockSupabase.from = jest.fn((table) => {
        if (table === 'items') return mockUpdateQuery;
        if (table === 'review_flags') return mockUpsertQuery;
        return {};
      }) as any;

      const result = await categoryService.flagForCategoryReview('item-123', 'Board Games');

      expect(result).toBe(true);

      // Verify item update
      expect(mockUpdateQuery.update).toHaveBeenCalledWith({
        requested_category_name: 'Board Games',
      });
      expect(mockUpdateQuery.eq).toHaveBeenCalledWith('id', 'item-123');

      // Verify review flag upsert
      expect(mockUpsertQuery.upsert).toHaveBeenCalledWith(
        expect.objectContaining({
          item_id: 'item-123',
          type: 'category_suggestion',
          details: expect.objectContaining({
            requested_name: 'Board Games',
          }),
        }),
        { onConflict: 'item_id,type' }
      );
    });

    it('should be idempotent (upsert for duplicate calls)', async () => {
      const mockUpdateQuery = {
        update: jest.fn().mockReturnThis(),
        eq: jest.fn().mockResolvedValue({ data: {}, error: null }),
      };

      const mockUpsertQuery = {
        upsert: jest.fn().mockResolvedValue({ data: {}, error: null }),
      };

      mockSupabase.from = jest.fn((table) => {
        if (table === 'items') return mockUpdateQuery;
        if (table === 'review_flags') return mockUpsertQuery;
        return {};
      }) as any;

      // Call twice with same data
      await categoryService.flagForCategoryReview('item-123', 'Puzzles');
      await categoryService.flagForCategoryReview('item-123', 'Puzzles');

      // Both calls should succeed
      expect(mockUpdateQuery.update).toHaveBeenCalledTimes(2);
      expect(mockUpsertQuery.upsert).toHaveBeenCalledTimes(2);

      // Verify onConflict ensures idempotency
      expect(mockUpsertQuery.upsert.mock.calls[0][1]).toEqual({ onConflict: 'item_id,type' });
    });

    it('should return false on item update error', async () => {
      const mockUpdateQuery = {
        update: jest.fn().mockReturnThis(),
        eq: jest.fn().mockResolvedValue({
          data: null,
          error: { message: 'Item not found' },
        }),
      };

      mockSupabase.from = jest.fn(() => mockUpdateQuery) as any;

      const result = await categoryService.flagForCategoryReview('item-999', 'Invalid');

      expect(result).toBe(false);
    });

    it('should still return true if review_flags table does not exist', async () => {
      const mockUpdateQuery = {
        update: jest.fn().mockReturnThis(),
        eq: jest.fn().mockResolvedValue({ data: {}, error: null }),
      };

      const mockUpsertQuery = {
        upsert: jest.fn().mockResolvedValue({
          data: null,
          error: { message: 'relation "review_flags" does not exist', code: '42P01' },
        }),
      };

      mockSupabase.from = jest.fn((table) => {
        if (table === 'items') return mockUpdateQuery;
        if (table === 'review_flags') return mockUpsertQuery;
        return {};
      }) as any;

      // Console.warn should be called, but function should still return true
      const warnSpy = jest.spyOn(console, 'warn').mockImplementation();

      const result = await categoryService.flagForCategoryReview('item-123', 'Test');

      expect(result).toBe(true);
      expect(warnSpy).toHaveBeenCalled();

      warnSpy.mockRestore();
    });
  });

  describe('getRecentCategories', () => {
    it('should return recent categories from AsyncStorage', async () => {
      const recentCategories = [
        { id: 'cat-1', name: 'Toys' },
        { id: 'cat-2', name: 'Books' },
        { id: 'cat-3', name: 'Clothing' },
      ];

      mockAsyncStorage.getItem.mockResolvedValue(JSON.stringify(recentCategories));

      const result = await categoryService.getRecentCategories('seller-123');

      expect(mockAsyncStorage.getItem).toHaveBeenCalledWith(
        '@kids_marketplace:recent_categories_seller-123'
      );
      expect(result).toEqual(recentCategories);
    });

    it('should return empty array when no recent categories stored', async () => {
      mockAsyncStorage.getItem.mockResolvedValue(null);

      const result = await categoryService.getRecentCategories('seller-456');

      expect(result).toEqual([]);
    });

    it('should return empty array on AsyncStorage error', async () => {
      mockAsyncStorage.getItem.mockRejectedValue(new Error('Storage error'));

      const errorSpy = jest.spyOn(console, 'error').mockImplementation();

      const result = await categoryService.getRecentCategories('seller-789');

      expect(result).toEqual([]);
      expect(errorSpy).toHaveBeenCalled();

      errorSpy.mockRestore();
    });
  });

  describe('saveRecentCategory', () => {
    it('should save category and maintain LRU order (max 3)', async () => {
      const existingRecent = [
        { id: 'cat-1', name: 'Toys' },
        { id: 'cat-2', name: 'Books' },
      ];

      mockAsyncStorage.getItem.mockResolvedValue(JSON.stringify(existingRecent));
      mockAsyncStorage.setItem.mockResolvedValue();

      await categoryService.saveRecentCategory('seller-123', { id: 'cat-3', name: 'Clothing' });

      // Verify new category added to front
      const expectedRecent = [
        { id: 'cat-3', name: 'Clothing' },
        { id: 'cat-1', name: 'Toys' },
        { id: 'cat-2', name: 'Books' },
      ];

      expect(mockAsyncStorage.setItem).toHaveBeenCalledWith(
        '@kids_marketplace:recent_categories_seller-123',
        JSON.stringify(expectedRecent)
      );
    });

    it('should remove oldest category when exceeding max (3)', async () => {
      const existingRecent = [
        { id: 'cat-1', name: 'Toys' },
        { id: 'cat-2', name: 'Books' },
        { id: 'cat-3', name: 'Clothing' },
      ];

      mockAsyncStorage.getItem.mockResolvedValue(JSON.stringify(existingRecent));
      mockAsyncStorage.setItem.mockResolvedValue();

      await categoryService.saveRecentCategory('seller-123', { id: 'cat-4', name: 'Games' });

      // Verify oldest (cat-3) was removed
      const expectedRecent = [
        { id: 'cat-4', name: 'Games' },
        { id: 'cat-1', name: 'Toys' },
        { id: 'cat-2', name: 'Books' },
      ];

      expect(mockAsyncStorage.setItem).toHaveBeenCalledWith(
        '@kids_marketplace:recent_categories_seller-123',
        JSON.stringify(expectedRecent)
      );
    });

    it('should move existing category to front (LRU)', async () => {
      const existingRecent = [
        { id: 'cat-1', name: 'Toys' },
        { id: 'cat-2', name: 'Books' },
        { id: 'cat-3', name: 'Clothing' },
      ];

      mockAsyncStorage.getItem.mockResolvedValue(JSON.stringify(existingRecent));
      mockAsyncStorage.setItem.mockResolvedValue();

      // Re-select cat-2 (Books)
      await categoryService.saveRecentCategory('seller-123', { id: 'cat-2', name: 'Books' });

      // cat-2 should move to front
      const expectedRecent = [
        { id: 'cat-2', name: 'Books' },
        { id: 'cat-1', name: 'Toys' },
        { id: 'cat-3', name: 'Clothing' },
      ];

      expect(mockAsyncStorage.setItem).toHaveBeenCalledWith(
        '@kids_marketplace:recent_categories_seller-123',
        JSON.stringify(expectedRecent)
      );
    });

    it('should handle AsyncStorage error gracefully', async () => {
      mockAsyncStorage.getItem.mockResolvedValue(JSON.stringify([]));
      mockAsyncStorage.setItem.mockRejectedValue(new Error('Storage full'));

      const errorSpy = jest.spyOn(console, 'error').mockImplementation();

      await categoryService.saveRecentCategory('seller-123', { id: 'cat-1', name: 'Toys' });

      expect(errorSpy).toHaveBeenCalled();

      errorSpy.mockRestore();
    });
  });

  describe('getCategoriesWithCounts', () => {
    it('should fetch categories with item counts', async () => {
      const mockCategories = [
        { id: 'cat-1', name: 'Toys', icon: '🧸', is_active: true, display_order: 1 },
        { id: 'cat-2', name: 'Books', icon: '📚', is_active: true, display_order: 2 },
      ];

      const mockSelectQuery = {
        select: jest.fn().mockReturnThis(),
        eq: jest.fn().mockReturnThis(),
        order: jest.fn().mockResolvedValue({ data: mockCategories, error: null }),
      };

      const mockCountQuery = {
        select: jest.fn().mockReturnThis(),
        eq: jest.fn().mockReturnThis(),
      };

      mockSupabase.from = jest.fn((table) => {
        if (table === 'categories') return mockSelectQuery;
        if (table === 'items') {
          // Return different counts for each category
          const calls = mockCountQuery.eq.mock.calls.length;
          if (calls === 0) {
            mockCountQuery.eq.mockResolvedValueOnce({ count: 5, error: null });
          } else {
            mockCountQuery.eq.mockResolvedValueOnce({ count: 3, error: null });
          }
          return mockCountQuery;
        }
        return {};
      }) as any;

      const result = await categoryService.getCategoriesWithCounts(false);

      expect(result).toHaveLength(2);
      expect(result[0].id).toBe('cat-1');
      expect(result[0].item_count).toBeDefined();
      expect(result[1].id).toBe('cat-2');
      expect(result[1].item_count).toBeDefined();
    });

    it('should filter inactive categories by default', async () => {
      const mockSelectQuery = {
        select: jest.fn().mockReturnThis(),
        eq: jest.fn().mockReturnThis(),
        order: jest.fn().mockResolvedValue({ data: [], error: null }),
      };

      mockSupabase.from = jest.fn(() => mockSelectQuery) as any;

      await categoryService.getCategoriesWithCounts(false);

      expect(mockSelectQuery.eq).toHaveBeenCalledWith('is_active', true);
    });

    it('should include inactive categories when requested', async () => {
      const mockSelectQuery = {
        select: jest.fn().mockReturnThis(),
        eq: jest.fn(),
        order: jest.fn().mockResolvedValue({ data: [], error: null }),
      };

      mockSupabase.from = jest.fn(() => mockSelectQuery) as any;

      await categoryService.getCategoriesWithCounts(true);

      expect(mockSelectQuery.eq).not.toHaveBeenCalled();
    });
  });
});
"}

{"content": "/**
 * Unit tests for useItemDraft hook
 * MODULE-04 LISTING-V3: TASK LISTING-V3-010
 * Tests 30s debounce, blur-flush, saveNow
 */

import { renderHook, act, waitFor } from '@testing-library/react-native';
import { useItemDraft } from '../../hooks/useItemDraft';
import * as draftService from '../../services/draftService';
import { AppState } from 'react-native';

// Mock draftService
jest.mock('../../services/draftService', () => ({
  createItemDraft: jest.fn(),
  getItemDraft: jest.fn(),
  updateItemDraft: jest.fn(),
  deleteItemDraft: jest.fn(),
}));

// Mock navigation
jest.mock('@react-navigation/native', () => ({
  useFocusEffect: (callback: any) => {
    // Execute callback immediately for testing
    callback();
  },
}));

const mockDraftService = draftService as jest.Mocked<typeof draftService>;

describe('useItemDraft', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    jest.useFakeTimers();
  });

  afterEach(() => {
    jest.runOnlyPendingTimers();
    jest.useRealTimers();
  });

  it('should load existing draft on mount when draftId provided', async () => {
    const mockDraft = {
      id: 'draft-123',
      seller_id: 'seller-123',
      draft_data: { title: 'Test Item' },
      photo_urls: [],
      ai_suggestions: null,
      step: 'photos',
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
      expires_at: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
    };

    mockDraftService.getItemDraft.mockResolvedValue(mockDraft);

    const { result } = renderHook(() => useItemDraft('draft-123', 'seller-123'));

    // Initially loading
    expect(result.current.isLoading).toBe(true);

    // Wait for load
    await waitFor(() => {
      expect(result.current.isLoading).toBe(false);
    });

    expect(mockDraftService.getItemDraft).toHaveBeenCalledWith('draft-123');
    expect(result.current.draft).toEqual(mockDraft);
  });

  it('should create new draft on mount when no draftId provided', async () => {
    const mockNewDraft = {
      id: 'draft-new',
      seller_id: 'seller-456',
      draft_data: {},
      photo_urls: [],
      step: 'photos',
    };

    mockDraftService.createItemDraft.mockResolvedValue(mockNewDraft);

    const { result } = renderHook(() => useItemDraft(undefined, 'seller-456'));

    await waitFor(() => {
      expect(result.current.isLoading).toBe(false);
    });

    expect(mockDraftService.createItemDraft).toHaveBeenCalledWith('seller-456', {});
    expect(result.current.draft).toEqual(mockNewDraft);
  });

  it('should auto-save every 30 seconds', async () => {
    const mockDraft = {
      id: 'draft-auto',
      seller_id: 'seller-789',
      draft_data: { title: 'Auto Save Test' },
      photo_urls: [],
      step: 'details',
    };

    mockDraftService.getItemDraft.mockResolvedValue(mockDraft);
    mockDraftService.updateItemDraft.mockResolvedValue(mockDraft);

    const { result } = renderHook(() => useItemDraft('draft-auto', 'seller-789'));

    await waitFor(() => {
      expect(result.current.draft).toBeDefined();
    });

    // Make changes
    act(() => {
      result.current.save({ title: 'Updated Title' });
    });

    // Fast-forward 29 seconds (should not save yet)
    act(() => {
      jest.advanceTimersByTime(29000);
    });

    expect(mockDraftService.updateItemDraft).not.toHaveBeenCalled();

    // Fast-forward 1 more second (total 30s, should trigger save)
    await act(async () => {
      jest.advanceTimersByTime(1000);
      await Promise.resolve(); // Flush promises
    });

    await waitFor(() => {
      expect(mockDraftService.updateItemDraft).toHaveBeenCalledWith('draft-auto', {
        title: 'Updated Title',
      });
    });
  });

  it('should flush pending changes on saveNow call', async () => {
    const mockDraft = {
      id: 'draft-immediate',
      seller_id: 'seller-now',
      draft_data: {},
      photo_urls: [],
      step: 'photos',
    };

    mockDraftService.getItemDraft.mockResolvedValue(mockDraft);
    mockDraftService.updateItemDraft.mockResolvedValue(mockDraft);

    const { result } = renderHook(() => useItemDraft('draft-immediate', 'seller-now'));

    await waitFor(() => {
      expect(result.current.draft).toBeDefined();
    });

    // Make changes
    act(() => {
      result.current.save({ title: 'Immediate Save' });
    });

    // Call saveNow without waiting for 30s timer
    await act(async () => {
      await result.current.saveNow();
    });

    expect(mockDraftService.updateItemDraft).toHaveBeenCalledWith('draft-immediate', {
      title: 'Immediate Save',
    });
  });

  it('should set isSaving state during save operation', async () => {
    const mockDraft = {
      id: 'draft-saving',
      seller_id: 'seller-saving',
      draft_data: {},
      photo_urls: [],
      step: 'photos',
    };

    mockDraftService.getItemDraft.mockResolvedValue(mockDraft);
    mockDraftService.updateItemDraft.mockImplementation(
      () =>
        new Promise((resolve) =>
          setTimeout(() => resolve(mockDraft), 100)
        )
    );

    const { result } = renderHook(() => useItemDraft('draft-saving', 'seller-saving'));

    await waitFor(() => {
      expect(result.current.draft).toBeDefined();
    });

    act(() => {
      result.current.save({ title: 'Saving Test' });
    });

    // Start save
    const savePromise = act(async () => {
      await result.current.saveNow();
    });

    // Should show isSaving immediately
    expect(result.current.isSaving).toBe(true);

    // Wait for save to complete
    await savePromise;

    // Should clear isSaving
    await waitFor(() => {
      expect(result.current.isSaving).toBe(false);
    });
  });

  it('should expose saveError and never throw', async () => {
    const mockDraft = {
      id: 'draft-error',
      seller_id: 'seller-error',
      draft_data: {},
      photo_urls: [],
      step: 'photos',
    };

    mockDraftService.getItemDraft.mockResolvedValue(mockDraft);
    mockDraftService.updateItemDraft.mockRejectedValue(
      new Error('Network error')
    );

    const { result } = renderHook(() => useItemDraft('draft-error', 'seller-error'));

    await waitFor(() => {
      expect(result.current.draft).toBeDefined();
    });

    act(() => {
      result.current.save({ title: 'Error Test' });
    });

    // Attempt save (should fail)
    await act(async () => {
      await result.current.saveNow();
    });

    // Should expose error, not throw
    expect(result.current.saveError).toBe('Network error');
    expect(result.current.isSaving).toBe(false);
  });

  it('should discard draft and call deleteItemDraft', async () => {
    const mockDraft = {
      id: 'draft-discard',
      seller_id: 'seller-discard',
      draft_data: {},
      photo_urls: [],
      step: 'photos',
    };

    mockDraftService.getItemDraft.mockResolvedValue(mockDraft);
    mockDraftService.deleteItemDraft.mockResolvedValue(true);

    const { result } = renderHook(() => useItemDraft('draft-discard', 'seller-discard'));

    await waitFor(() => {
      expect(result.current.draft).toBeDefined();
    });

    // Discard draft
    await act(async () => {
      await result.current.discard();
    });

    expect(mockDraftService.deleteItemDraft).toHaveBeenCalledWith('draft-discard');
    expect(result.current.draft).toBeNull();
  });

  it('should accumulate multiple save calls before flush', async () => {
    const mockDraft = {
      id: 'draft-accumulate',
      seller_id: 'seller-acc',
      draft_data: {},
      photo_urls: [],
      step: 'photos',
    };

    mockDraftService.getItemDraft.mockResolvedValue(mockDraft);
    mockDraftService.updateItemDraft.mockResolvedValue(mockDraft);

    const { result } = renderHook(() => useItemDraft('draft-accumulate', 'seller-acc'));

    await waitFor(() => {
      expect(result.current.draft).toBeDefined();
    });

    // Make multiple changes
    act(() => {
      result.current.save({ title: 'First Change' });
    });

    act(() => {
      result.current.save({ description: 'Second Change' });
    });

    act(() => {
      result.current.save({ price: 25.0 });
    });

    // Flush all changes at once
    await act(async () => {
      await result.current.saveNow();
    });

    // Should merge all updates
    expect(mockDraftService.updateItemDraft).toHaveBeenCalledWith('draft-accumulate', {
      title: 'First Change',
      description: 'Second Change',
      price: 25.0,
    });
  });

  it('should not create draft on mount when autoCreateOnMount is false', async () => {
    const { result } = renderHook(() =>
      useItemDraft(undefined, 'seller-no-auto', { autoCreateOnMount: false })
    );

    await waitFor(() => {
      expect(result.current.isLoading).toBe(false);
    });

    expect(mockDraftService.createItemDraft).not.toHaveBeenCalled();
    expect(result.current.draft).toBeNull();
  });
});
